const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("custom slug validation enforces length AND pattern together", async () => {
  const { base, close } = startServer();
  try {
    const tooShortButPatternOk = await api(base, "POST", "/api/links", { url: "https://example.com", slug: "ab" });
    assert.strictEqual(tooShortButPatternOk.status, 400);

    const rightLengthBadPattern = await api(base, "POST", "/api/links", { url: "https://example.com", slug: "ABCDEF" });
    assert.strictEqual(rightLengthBadPattern.status, 400);

    const rightLengthBadChars = await api(base, "POST", "/api/links", { url: "https://example.com", slug: "abc_def" });
    assert.strictEqual(rightLengthBadChars.status, 400);

    const valid = await api(base, "POST", "/api/links", { url: "https://example.com", slug: "my-story" });
    assert.strictEqual(valid.status, 201);
  } finally {
    await close();
  }
});

